package com.example.paymentservicefeb25.controllers;
import com.example.paymentservicefeb25.services.PaymentService; import com.example.paymentservicefeb25.dtos.PaymentInitiateRequest; import com.stripe.exception.StripeException; import org.springframework.web.bind.annotation.*; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Positive; import org.springframework.validation.annotation.Validated;
@RestController @Validated @RequestMapping("/payments") public class PaymentController { private final PaymentService service; public PaymentController(PaymentService service){this.service=service;} @PostMapping("/initiate/{orderId}") public String initiate(@PathVariable @Positive(message="orderId must be positive") Long orderId,@RequestHeader(value="Idempotency-Key",required=false) @NotBlank(message="Idempotency-Key is required") String key,@jakarta.validation.Valid @RequestBody PaymentInitiateRequest request)throws StripeException{return service.initiatePayment(orderId,request.amount(),key==null?"":key);} }
